/** Lines of source code that build SQL by joining or interpolating strings. */

/** Files whose lines are read. */
const SOURCE = /\.(ts|tsx|js|jsx|mjs|cjs|py|php|go|rb|java|kt|cs|rs)$/

/** SQL in upper case. */
const SQL_UPPER = /\bSELECT\b.*\bFROM\b|\bINSERT\s+INTO\b|\bUPDATE\s+\S+\s+SET\b|\bDELETE\s+FROM\b|\b(WHERE|VALUES|ORDER BY|GROUP BY|JOIN)\b/

/** SQL in any case, only in shapes English prose does not take ("select a file from the list" does not match). */
const SQL_ANY_CASE = /\bselect\s+(\*|[\w.]+(\s*,\s*[\w.]+)+)\s+from\b|\binsert\s+into\s+[\w."`]+\s*(\(|values\b|select\b)|\bdelete\s+from\s+[\w."`]+\s+where\b|\bupdate\s+[\w."`]+\s+set\s+\w+\s*=/i

/** Ways a line joins a value into a string, across the languages read. */
const JOINS = [
  /["']\s*\+\s*[\w$(]/, // "... " + value (JS, Java, Go, C#, Kotlin)
  /[\w)\]]\s*\+\s*["']/, // value + " ..."
  /\bf"[^"]*\{|\bf'[^']*\{/, // Python f-string
  /["']\s*%\s*[\w(]/, // Python % formatting
  /["']\s*\.format\(/, // Python str.format
  /["']\s*\.\s*\$\w|\$\w+\s*\.\s*["']/, // PHP "..." . $var
  /\$"[^"]*\{/, // C# $"... {x}"
  /\b(fmt\.Sprintf|String\.format|format!)\(/, // Go, Java, Rust formatting
]

/** Interpolation inside a double-quoted string body: PHP and Kotlin `$var`, Ruby `#{x}`. */
const INTERPOLATES = /\$[A-Za-z_{]|#\{/

/**
 * Whether a double-quoted string on the line interpolates a value. Only the text between a string's own
 * quotes is read, so `fetchRow("... = ?", [$id])` does not read its parameter array as part of the SQL.
 */
function interpolates(line: string): boolean {
  return [...line.matchAll(/"((?:[^"\\]|\\.)*)"/g)].some(m => INTERPOLATES.test(m[1] ?? ''))
}

/** The last name of a template tag that makes the values parameters: sql`...`, Prisma.sql`...`, prisma.$queryRaw`...`. */
const SAFE_TAG = /^(sql|SQL|\$queryRaw|\$executeRaw)$/

const isSafeTag = (tag: string): boolean => SAFE_TAG.test(tag.split('.').at(-1) ?? '')

const COMMENT = /^\s*(\/\/|#|\*|\/\*|--)/

export function isSource(path: string): boolean {
  return SOURCE.test(path)
}

function hasSql(text: string): boolean {
  return SQL_ANY_CASE.test(text) || SQL_UPPER.test(text)
}

/** A single line that holds SQL and joins a value into it; a line inside a template literal is left to `templateLines`. */
function joinsSql(line: string): boolean {
  if (COMMENT.test(line) || !hasSql(line)) return false
  const plain = line.replace(/`[^`]*`/g, '``')
  return JOINS.some(re => re.test(plain)) || interpolates(plain)
}

/** The lines with a `${` of each untagged or unsafe-tagged template literal that holds SQL. */
function templateLines(text: string): string[] {
  const out: string[] = []
  for (const m of text.matchAll(/([\w.$]*)`([^`]*)`/g)) {
    const body = m[2] ?? ''
    if (isSafeTag(m[1] ?? '') ||!body.includes('${') || !hasSql(body)) continue
    const first = body.split('\n').find(l => l.includes('${')) ?? ''
    const line = text.split('\n').find(l => l.includes(first.trim())) ?? first
    // A template inside a commented-out line builds nothing.
    if (!COMMENT.test(line)) out.push(line)
  }
  return out
}

/** The trimmed lines of `after` that build SQL from strings, without those `before` already had. */
export function sqlLines(before: string, after: string): string[] {
  const old = new Set(before.split('\n').map(l => l.trim()))
  const found = [...after.split('\n').filter(joinsSql), ...templateLines(after)].map(l => l.trim())
  return [...new Set(found)].filter(l => l !== '' && !old.has(l))
}

/**
 * The reported lines a file's text still builds SQL from strings with, measured by the same reading as a
 * new edit, so a line taken out, rewritten with parameters or commented out no longer counts.
 */
export function stillBuilt(text: string, lines: string[]): string[] {
  const built = sqlLines('', text)
  return lines.filter(l => built.some(b => b.includes(l)))
}

/** The place of each line in the file's text now, or the bare file when the text was not read. */
export function placesOf(shown: string, text: string | undefined, lines: string[]): string[] {
  return lines.map(l => {
    const n = text === undefined ? undefined : lineOf(text, l)
    return n === undefined ? shown : `${shown}:${n}`
  })
}

/** The 1-based number of the first line of `text` that holds `line`; an Edit's text can be part of a line. */
export function lineOf(text: string, line: string): number | undefined {
  const i = text.split('\n').findIndex(l => l.includes(line))
  return i < 0 ? undefined : i + 1
}

/** `path` shown relative to the session directory when it is inside it. */
export function shownPath(path: string, cwd: string): string {
  const base = `${cwd.replace(/\/+$/, '')}/`
  return path.startsWith(base) ? path.slice(base.length) : path
}

/** At most this many places are named, the rest counted. */
const MAX_NAMED = 8

function namedPlaces(places: string[]): string {
  const named = places.slice(0, MAX_NAMED)
  if (places.length > MAX_NAMED) named.push(`${places.length - MAX_NAMED} more`)
  return named.join(' · ')
}

export function noteText(places: string[]): string {
  return `sql-concat-watch: this edit builds SQL from strings: ${namedPlaces(places)}. Pass values as query parameters (?, $1, :name) instead of joining them into the SQL text.`
}

/**
 * The note the model reads at the next prompt while a finding stands, so a finding it did not close
 * reaches it again instead of standing in the pane alone. The person reads the pane and needs no line.
 */
export function openNote(places: string[]): string {
  return `sql-concat-watch: ${places.length} place(s) still build SQL from strings: ${namedPlaces(places)}. Pass the values as query parameters (?, $1, :name), or take the lines out.`
}

/** The transcript line: the places alone, without the instruction the model reads. The engine adds the mod name. */
export function logText(places: string[]): string {
  return `SQL built from strings: ${namedPlaces(places)}`
}

/** A sidebar line of a finding or its closing; the count of the places left unnamed is faint. */
export type Line = { text: string; kind: 'error' | 'ok' | 'dim' }

/**
 * One line per named place in the finding's colour, and the places past `MAX_NAMED` as one faint count,
 * so the count does not read as one more place.
 */
function placeLines(places: string[], kind: 'error' | 'ok'): Line[] {
  const named: Line[] = places.slice(0, MAX_NAMED).map(text => ({ text, kind }))
  return places.length > MAX_NAMED ? [...named, { text: `${places.length - MAX_NAMED} more`, kind: 'dim' }] : named
}

/** One sidebar line per place, so the section reads as a list. */
export function sidebarLines(places: string[]): Line[] {
  return placeLines(places, 'error')
}

/** The transcript line of a finding a later edit closed. */
export function doneLog(file: string, places: string[]): string {
  return `the SQL built from strings is gone from ${file}: ${namedPlaces(places)}`
}

/** The sidebar lines of a closed finding: the file, then the places the strings left. */
export function doneLines(file: string, places: string[]): Line[] {
  return [{ text: file, kind: 'ok' }, ...placeLines(places, 'ok')]
}

/** The global flags git takes before the subcommand, so `git -c user.name=x commit` is still a commit. */
const GIT_FLAG = String.raw`(?:\s+-[cC]\s+\S+|\s+--(?:git-dir|work-tree|namespace)=\S+|\s+--(?:no-pager|no-replace-objects|bare|literal-pathspecs|paginate))`

/** A `git commit`, `git push` or `git merge` the gate stops while a finding is open. */
const GUARDED = new RegExp(String.raw`(^|[\s;&|(])git(?:${GIT_FLAG})*\s+(commit|push|merge)\b`)
const ASKING = /\s(--dry-run|--help|-h)(\s|$)/

export function isGuarded(command: string): boolean {
  return GUARDED.test(command) && !ASKING.test(command)
}

/** Whether the command is a `git commit`, the one guarded command whose own files can be measured. */
export function isCommit(command: string): boolean {
  return GUARDED.exec(command)?.[2] === 'commit'
}

/**
 * Whether the index alone says what this commit holds. A `-a` or `-am` commit stages the tracked files
 * as it runs, and a pathspec after `--` commits paths the index does not hold, so neither is narrowed.
 */
export function isNarrowable(command: string): boolean {
  const words = command.split(/\s+/)
  return !words.includes('--') && !words.some(w => w === '--all' || /^-[A-Za-z]*a/.test(w))
}

/** The mode of the mod: a note only, or a note and a gate on git commit, push and merge. */
export type Mode = 'note' | 'deny'

/** The mode a `/sql-concat-watch mode <word>` argument names, or undefined when it is not one. */
export function modeOf(arg: string): Mode | undefined {
  return arg === 'note' || arg === 'deny' ? arg : undefined
}

/** The deny text both the model and the person read: where the SQL is built, and the one way out. */
export function denyText(places: readonly string[]): string {
  return `stopped: ${places.length} place(s) build SQL from strings: ${namedPlaces([...places])}. Pass the values as query parameters (?, $1, :name), then run the command again; there is no way around this gate.`
}

/** A sidebar section key: the subject cut to what the sidebar takes, so one file keeps one section. */
export function sectionKey(text: string): string {
  return text.replace(/[^A-Za-z0-9._:-]+/g, '-').slice(0, 64) || 'note'
}

